representation.shell_command:
set -eu
Rscript -e '
data <- read.table("$(inputs.input.path)", header=TRUE, sep="\t", stringsAsFactors=FALSE, na.strings="");
data <- data[!is.na(data$Age) & data$Efficacy != "", ];
data$response <- ifelse(data$Efficacy == "PR", 1, 0);
model <- glm(response ~ Age, data=data, family=binomial);
coef_table <- coef(summary(model));
write.table(data.frame(Variable=rownames(coef_table), coef_table, check.names=FALSE), file="coefficients.tsv", sep="\t", row.names=FALSE, quote=FALSE);
'

